namespace ghidra.app.cmd.function;

using ghidra.framework.cmd;
using ghidra.program.model.listing;

/**
 * Command for assigning a tag to a function
 */
public class CreateFunctionTagCmd : Command<Program> {

	private string name;
	private string comment;

	/**
	 * Constructor
	 * 
	 * @param name the name of the new tag
	 */
	public CreateFunctionTagCmd(string name) {
		this.name = name;
		this.comment = "";
	}

	/**
	 * Constructor
	 * 
	 * @param name the name of the new tag
	 * @param comment the tag comment
	 */
	public CreateFunctionTagCmd(string name, string comment) {
		this.name = name;
		this.comment = comment;
	}

	/* @Override */
	public bool applyTo(Program program) {
		FunctionManager functionManager = program.getFunctionManager();
		FunctionTagManager tagManager = functionManager.getFunctionTagManager();
		tagManager.createFunctionTag(name, comment);
		return true;
	}

	/* @Override */
	public string getName() {
		return "Create Function Tag";
	}

	/* @Override */
	public string getStatusMsg() {
		return null;
	}
}
